const cfg = $('Config — Client Settings').first().json;
const te = ($('Graph — Fetch Time Entries').first().json.value) || [];
const projects = ($('Graph — Fetch Projects').first().json.value) || [];
const guidelines = ($('Graph — Fetch Billing Guidelines').first().json.value) || [];
const clients = ($('Graph — Fetch Clients').first().json.value) || [];

const projById = {};
for (const p of projects) { projById[String(p.id)] = p.fields || {}; }

const clientNameById = {};
for (const c of clients) {
  const cf = c.fields || {};
  clientNameById[String(c.id)] = String(cf[cfg.clientTitleField] || '');
}

const firmRules = String(cfg.firmBillingRules || '').trim();

const out = [];
for (const item of te) {
  const f = item.fields || {};
  const narrative = String(f[cfg.fieldNarrative] || '').trim();
  const status = String(f[cfg.fieldStatus] || '').trim();
  if (!narrative) continue;
  if (status !== cfg.statusToProcess) continue;

  const projLookupId = (f[cfg.teProjectIdField] !== undefined && f[cfg.teProjectIdField] !== null) ? String(f[cfg.teProjectIdField]) : null;
  const proj = (projLookupId && projById[projLookupId]) ? projById[projLookupId] : null;
  const clientLookupId = (proj && proj[cfg.projClientIdField] !== undefined && proj[cfg.projClientIdField] !== null) ? String(proj[cfg.projClientIdField]) : null;
  const clientName = (clientLookupId && clientNameById[clientLookupId]) ? clientNameById[clientLookupId] : '';

  const applicable = [];
  for (const g of guidelines) {
    const gf = g.fields || {};
    const gClientId = (gf[cfg.bgClientIdField] !== undefined && gf[cfg.bgClientIdField] !== null) ? String(gf[cfg.bgClientIdField]) : null;
    // Guidelines with no client are firm-wide; client-specific ones must match this entry's client
    if (!gClientId || (clientLookupId && gClientId === clientLookupId)) {
      const title = String(gf.Title || '').trim();
      const instruction = String(gf[cfg.fieldInstruction] || '').trim();
      if (instruction) { applicable.push((title ? title + ': ' : '') + instruction); }
    }
  }
  let guidelinesText = applicable.length
    ? applicable.map(function (a) { return '- ' + a; }).join('\n')
    : 'None on file. Apply general legal billing best practices only.';
  // Firm-wide rules from Config (block-billing bans, minimum increments, forbidden phrases, etc.)
  if (firmRules) {
    guidelinesText = 'FIRM-WIDE BILLING RULES (always apply):\n' + firmRules + '\n\nCLIENT GUIDELINES:\n' + guidelinesText;
  }

  out.push({ json: {
    itemId: String(item.id),
    title: String(f.Title || ''),
    narrative: narrative,
    hours: (f.Hours !== undefined && f.Hours !== null) ? f.Hours : '',
    projectName: proj ? String(proj.Title || '') : '',
    clientName: clientName,
    guidelinesText: guidelinesText,
    existingNotes: String(f[cfg.fieldNotes] || '')
  }});
}
return out;

