const cfg = $('Config — Client Settings').first().json;
const entry = $('Loop — Each Time Entry').first().json;
const resp = $input.first().json;

// Extract the model output across possible response shapes.
// With a strict json_schema output format, output[].content[].text arrives as an ALREADY-PARSED OBJECT.
let raw;
if (Array.isArray(resp.output)) {
  const msg = resp.output.find(function (o) { return o.type === 'message' && Array.isArray(o.content); });
  if (msg) {
    const part = msg.content.find(function (c) { return c.type === 'output_text' || c.text !== undefined; });
    if (part) { raw = part.text; }
  }
}
if (raw === undefined) {
  if (resp.message && resp.message.content !== undefined) { raw = resp.message.content; }
  else if (resp.output_text !== undefined) { raw = resp.output_text; }
  else if (resp.text !== undefined) { raw = resp.text; }
  else { raw = resp; }
}

let parsed;
if (typeof raw === 'string') {
  const clean = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} else {
  parsed = raw; // already an object — use as-is
}
if (Array.isArray(parsed)) { parsed = parsed[0]; }
if ((!parsed || parsed.aiNarrative === undefined) && resp.aiNarrative !== undefined) { parsed = resp; }

const aiNarrative = String((parsed && parsed.aiNarrative) || '').trim();
const issues = (parsed && Array.isArray(parsed.issues)) ? parsed.issues.map(function (i) { return String(i); }) : [];
const compliant = (parsed && parsed.compliant !== false) && issues.length === 0;

if (!aiNarrative) { throw new Error('AI returned an empty aiNarrative for item ' + entry.itemId + '. Raw response keys: ' + Object.keys(resp).join(', ')); }

const body = {};
body[cfg.fieldAiNarrative] = aiNarrative;
body[cfg.fieldStatus] = issues.length ? cfg.statusFlagged : cfg.statusAfter;
if (issues.length) {
  const stamp = new Date().toLocaleString('en-US', {
    timeZone: cfg.noteTimezone || 'America/Chicago',
    month: 'short', day: 'numeric', year: 'numeric',
    hour: 'numeric', minute: '2-digit', hour12: true
  });
  const noteLine = stamp + ' — AI Billing Review: ' + issues.join(' | ');
  body[cfg.fieldNotes] = entry.existingNotes ? (entry.existingNotes + '\n' + noteLine) : noteLine;
}

return [{ json: {
  itemId: entry.itemId,
  title: entry.title,
  clientName: entry.clientName,
  projectName: entry.projectName,
  aiNarrative: aiNarrative,
  compliant: compliant,
  issues: issues,
  updateBody: body
}}];

const cfg = $('Config — Client Settings').first().json;

// Accumulate results across all loop iterations of the Parse node
let results = [];
let run = 0;
while (run < 1000) {
  let items;
  try { items = $('Parse — AI Output').all(0, run); } catch (e) { break; }
  if (!items || !items.length) break;
  results = results.concat(items.map(function (i) { return i.json; }));
  run++;
}

if (!results.length) { return []; }

const flagged = results.filter(function (r) { return !r.compliant; });
const rows = results.map(function (r) {
  const flag = r.compliant ? '' : ' style="background:#fdecea"';
  return '<tr' + flag + '>' +
    '<td style="padding:6px 10px;border:1px solid #c9c7c8;">' + (r.title || '(untitled)') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #c9c7c8;">' + (r.clientName || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #c9c7c8;">' + (r.compliant ? 'Compliant' : 'Flagged') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #c9c7c8;">' + (r.issues.length ? r.issues.join('<br>') : '-') + '</td>' +
    '</tr>';
}).join('');

const html = '<div style="font-family:Aptos,Roboto,Arial,sans-serif;color:#002657;">' +
  '<h2 style="color:#002657;">AI Narrative Review — Run Summary</h2>' +
  '<p><strong>' + results.length + '</strong> time entries processed &nbsp;|&nbsp; <strong>' + flagged.length + '</strong> flagged for billing guideline issues.</p>' +
  '<table style="border-collapse:collapse;font-size:14px;">' +
  '<tr style="background:#002657;color:#ffffff;">' +
  '<th style="padding:6px 10px;border:1px solid #c9c7c8;text-align:left;">Entry</th>' +
  '<th style="padding:6px 10px;border:1px solid #c9c7c8;text-align:left;">Client</th>' +
  '<th style="padding:6px 10px;border:1px solid #c9c7c8;text-align:left;">Result</th>' +
  '<th style="padding:6px 10px;border:1px solid #c9c7c8;text-align:left;">Issues</th>' +
  '</tr>' + rows + '</table>' +
  '<p style="color:#9e9e9e;font-size:12px;">Automated by the Time Entry AI Narrative workflow.</p></div>';

return [{ json: {
  subject: 'AI Narrative Review: ' + results.length + ' processed, ' + flagged.length + ' flagged',
  html: html,
  to: cfg.digestTo,
  cc: cfg.digestCc
}}];
